out.push(stage('7P', 'Respond'));
out.push(p('⚠ **The slip asks whether the count adds up, and it is the fastest useful thing a reviewer can do.** ⚠ **It takes five seconds, it is objective, and when it fails it has found a writer who does not know the state of their own obligations** — **which is a bigger finding than any sentence in the text.**'));
out.push(stage('7R', 'Share'));
